<script setup lang="ts">
import { onMounted, ref } from 'vue'; import { useRoute } from 'vue-router'; import { api, request, type Row } from '../api'; import { origins, date, iso } from '../utils'; import AsyncPanel from '../components/AsyncPanel.vue'; import StatusBadge from '../components/StatusBadge.vue'; import JsonDetails from '../components/JsonDetails.vue'
const route=useRoute(),asset=ref(''),contract=ref(''),origin=ref(''),from=ref(''),to=ref(''),events=ref<Row[]>([]),reports=ref<Row[]>([]),selected=ref<Row|null>(null),selectedId=ref(''),loading=ref(false),error=ref('')
async function load(){loading.value=true;error.value='';try{const[a,r]=await Promise.all([api.audit({asset_id:asset.value,contract_id:contract.value,origin:origin.value,from:iso(from.value),to:iso(to.value)}),api.reports()]);events.value=a.events??[];reports.value=r.reports??[]}catch(e){error.value=(e as Error).message}finally{loading.value=false}}
async function open(id:string){error.value='';try{const r=await request(`/reports/${encodeURIComponent(id)}`);selected.value=r.report??r;selectedId.value=id}catch(e){error.value=(e as Error).message}}
onMounted(async()=>{await load();if(typeof route.query.report==='string')await open(route.query.report)})
</script>
<template><section class="panel"><div class="panel-heading"><div><p class="eyebrow">IMMUTABLE EVIDENCE & RESEARCH RECORDS</p><h2>审计事件检索</h2></div><button class="button secondary" @click="load">刷新记录</button></div><form @submit.prevent="load" class="form-grid three"><label>资产 ID<input v-model="asset" placeholder="例如 clean" aria-label="审计资产ID"></label><label>合同 ID<input v-model="contract" placeholder="精确合同 ID" aria-label="审计合同ID"></label><label>证据来源<select v-model="origin"><option value="">全部来源（逐行保留标签）</option><option v-for="o in origins" :key="o.value" :value="o.value">{{ o.label }}</option></select></label><label>起始时间<input v-model="from" type="datetime-local"></label><label>截止时间<input v-model="to" type="datetime-local"></label><div class="form-button"><button class="button" type="submit">筛选审计事件</button></div></form></section><AsyncPanel :loading="loading" :error="error" @retry="load"><section class="panel"><h2>事件证据链 <span class="count-label">{{ events.length }} 条</span></h2><div class="table-wrap audit-table"><table><thead><tr><th>序号 / 时间</th><th>事件</th><th>资产 / 合同</th><th>来源</th><th>证据</th></tr></thead><tbody><tr v-for="(e,i) in events" :key="e.seq??e.event_id??i"><td>{{ e.seq??i+1 }}<small>{{ date(e.event_time??e.created_at??e.timestamp??e.at) }}</small></td><td>{{ e.kind??e.event_type??e.type??e.action }}</td><td>{{ e.display_asset_id??e.asset_id??e.body?.asset_id??e.payload?.asset_id??e.data?.asset_id??'—' }}<small class="mono">{{ e.contract_id??e.body?.contract_id??e.payload?.contract_id??e.data?.contract_id??'—' }}</small></td><td>{{ e.display_origin??e.origin??e.body?.origin??e.payload?.origin??e.data?.origin??'系统事件' }}</td><td><JsonDetails :data="e" title="查看事件"/></td></tr><tr v-if="!events.length"><td colspan="5" class="empty-cell">没有符合筛选条件的事件。</td></tr></tbody></table></div></section><section class="panel"><h2>保存的评估报告</h2><p class="muted small">刷新页面后从 Registry SQLite 重新读取；JSON 与打印视图均由后端保存的报告生成。</p><div class="table-wrap"><table><thead><tr><th>报告 ID</th><th>资产 / 任务</th><th>时点</th><th>状态</th><th>导出</th></tr></thead><tbody><tr v-for="r in reports" :key="r.report_id"><td><button class="link-button" @click="open(r.report_id)">{{ r.report_id }}</button></td><td>{{ r.asset_id??r.kind??r.interface }}<small>{{ r.task_id }}</small></td><td>{{ date(r.as_of_time??r.created_at) }}</td><td><StatusBadge :value="r.status"/></td><td><div class="actions"><a class="button secondary compact" :href="`/api/reports/${encodeURIComponent(r.report_id)}/export`" download>JSON</a><a class="button secondary compact" :href="`/api/reports/${encodeURIComponent(r.report_id)}/print`" target="_blank" rel="noopener">HTML / 打印</a></div></td></tr><tr v-if="!reports.length"><td colspan="5" class="empty-cell">尚无保存报告；请先完成一次价值评估或资产比较。</td></tr></tbody></table></div></section><section v-if="selected" class="panel"><div class="panel-heading"><h2>研究报告详情</h2><a class="button" :href="`/api/reports/${encodeURIComponent(selectedId)}/print`" target="_blank" rel="noopener">打开可读打印报告 ↗</a></div><dl class="details-grid"><dt>资产 / 精确版本</dt><dd>{{ selected.asset_id }} / {{ selected.asset_version??selected.result?.version }}</dd><dt>任务与评估时点</dt><dd>{{ selected.task_id }} / {{ date(selected.as_of_time) }}</dd><dt>测量来源</dt><dd>{{ selected.conditional_utility?.evidence_type??selected.source??'见完整报告' }}</dd><dt>状态</dt><dd><StatusBadge :value="selected.status"/></dd></dl><JsonDetails :data="selected" title="完整评估过程、信用历史、参数、区间与研究限制"/></section></AsyncPanel></template>
